
'use strict';
// Shared visual components and carpool gestures, retained from the approved UI prototype.
// Native screens, authentication, server persistence and notifications are wired in app.js.
const STORAGE_KEY='club-ops-demo-v2';
const DEMO_TODAY=ClubDomain.today();
const UID=()=> 'id_'+(crypto.randomUUID?crypto.randomUUID().replaceAll('-',''):[...crypto.getRandomValues(new Uint8Array(16))].map(b=>b.toString(16).padStart(2,'0')).join(''));
const clone=x=>JSON.parse(JSON.stringify(x));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const jpDate=(s,year=false)=>{const d=new Date(s+'T12:00:00');return `${year?d.getFullYear()+'年':''}${d.getMonth()+1}/${d.getDate()}（${'日月火水木金土'[d.getDay()]}）`;};
const money=n=>Number(n).toLocaleString('ja-JP')+'円';
function seed(){
 const people=[
 ['m1','池田',4,'above','university'],['m2','中島',4,'above','university'],['m3','山口',5,'above','station'],['m4','細川',3,'below','university'],['m5','井澤',3,'below','university'],['m6','小林',2,'below','university'],['m7','杉山',1,'below','university'],['m8','山田',2,'below','university'],['m9','江崎',1,'below','university'],['m10','木村',2,'below','station'],['m11','原塚',1,'below','station'],['m12','池谷',2,'below','station'],['m13','田中',6,'above','university'],['m14','佐藤',2,'below','university']
 ].map(([id,name,grade,seniority,pickup])=>({id,name,grade,seniority,pickup,memo:'',active:true,defaultOverride:null}));
 const events=[['e0','2026-09-03','19:00','21:00','v1'],['e1','2026-09-12','09:00','13:00','v2'],['e2','2026-09-15','19:00','21:00','v1'],['e3','2026-09-17','19:00','21:00','v1'],['e4','2026-09-19','09:00','13:00','v2'],['e5','2026-09-22','19:00','21:00','v1'],['e6','2026-10-03','09:00','13:00','v2'],['e7','2026-11-07','09:00','13:00','v1']].map(([id,date,start,end,venueId])=>({id,date,start,end,venueId,title:'練習',kind:'club',assignees:[],memo:''}));
 events.push({id:'ex1',date:'2026-09-12',start:'13:30',end:'14:00',title:'幹部会',kind:'executive',assignees:[],memo:'',venueId:''},{id:'ex2',date:'2026-09-15',start:'17:00',end:'17:30',title:'体育館打ち合わせ',kind:'executive',assignees:['u1','u2'],memo:'',venueId:''});
 const attendance={};events.filter(e=>e.kind==='club').forEach(e=>people.forEach(p=>attendance[e.id+'|'+p.id]=p.seniority==='below'||['m1','m2','m3','m13'].includes(p.id)));attendance['e1|m14']=false;attendance['e0|m14']=true;attendance['e0|m7']=false;
 const initial=[{id:'c1',pickup:'university',driver:'m1',riders:['m5','m6','m7']},{id:'c2',pickup:'university',driver:'m2',riders:['m4','m8']},{id:'c3',pickup:'station',driver:'m3',riders:['m10']}];
 const past=[{id:'p1',pickup:'university',driver:'m1',riders:['m5','m6','m14']},{id:'p2',pickup:'university',driver:'m2',riders:['m4','m8','m9']},{id:'p3',pickup:'station',driver:'m3',riders:['m10','m11','m12']}];
 const make=(id,eventId,cars,status)=>({id,eventId,linked:true,legs:{outbound:clone(cars),return:clone(cars)},enabled:{outbound:true,return:true},need:{outbound:{},return:{}},status,version:1,unitYen:300});
 return {schema:1,group:{id:'g1',name:'〇〇大学バドミントン部'},currentUser:'u1',operators:[{id:'u1',name:'細川'},{id:'u2',name:'池田'},{id:'u3',name:'中島'}],people,events,attendance,venues:[{id:'v1',name:'大学体育館',courts:4,memo:''},{id:'v2',name:'市民体育館',courts:3,memo:'入口で鍵を受け取る'},{id:'v3',name:'総合体育館',courts:6,memo:''}],tasks:[{id:'t1',title:'練習メニューを作成',date:'2026-09-11',time:'18:00',assignees:['u1'],done:false,memo:'',notifications:['P7D','P1D']},{id:'t2',title:'大会申込',date:'2026-09-15',time:'18:00',assignees:['u2'],done:false,memo:'',notifications:['P7D','P1D']},{id:'t3',title:'幹部会の資料を準備',date:'2026-09-12',time:'12:00',assignees:[],done:false,memo:'',relatedEventId:'ex1',notifications:['P1D']},{id:'t4',title:'体育館へ連絡',date:'2026-09-04',time:'18:00',assignees:['u1'],done:true,memo:'',notifications:[]}],notices:[{id:'n1',title:'土曜の体育館を変更',body:'9月12日は市民体育館で練習します。',date:'2026-09-05',author:'池田',assignees:[],notify:true},{id:'n2',title:'大会申込について',body:'申込内容は幹部会で確認します。',date:'2026-09-03',author:'中島',assignees:[],notify:false}],equipment:[{id:'i1',name:'シャトル',quantity:4,unit:'筒',memo:'',threshold:5},{id:'i2',name:'テーピング',quantity:6,unit:'個',memo:'',threshold:null},{id:'i3',name:'救急セット',quantity:1,unit:'組',memo:'',threshold:null}],plans:[make('plan1','e1',initial,'draft'),make('plan0','e0',past,'registered')],settings:{unitYen:300,reminders:['P7D','P1D']},roles:{予定:['u1','u2'],やること:['u1'],お知らせ:['u1','u2'],出欠:['u1'],配車:['u1','u2'],体育館:['u2'],練習メニュー:['u1'],備品:['u3']}};
}
let state;try{state=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(!state||state.schema!==1)state=seed();}catch{state=seed();}
let ui={taskTab:'self',attendanceMode:'date',attendanceEvent:'e1',attendanceMember:'m4',calendarYear:2026,calendarMonth:8,showExec:false,carTab:'future',leg:'outbound',selectedPerson:null,memberFilter:'all'};
let undoState=null,toastTimer=null;
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true}catch{toast('この環境では保存できません');return false}}
function checkpoint(){undoState=clone(state)}
function toast(text,undo=false){clearTimeout(toastTimer);document.getElementById('toast-root').innerHTML=`<div class="toast">${esc(text)}${undo?'<button data-act="undo">元に戻す</button>':''}</div>`;toastTimer=setTimeout(()=>document.getElementById('toast-root').innerHTML='',4500)}
const paths={home:'<path d="m3 10 9-7 9 7v10H14v-6h-4v6H3z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18m-13 4h2m4 0h2m-8 3h2"/>',task:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="m7 12 3 3 7-7"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',settings:'<path d="m9 3-1 3-3 1v3l-2 2 2 2v3l3 1 1 3h6l1-3 3-1v-3l2-2-2-2V7l-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',back:'<path d="m15 5-7 7 7 7"/>',chev:'<path d="m9 5 7 7-7 7"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<path d="m5 12 4 4 10-10"/>',car:'<path d="m5 8 2-5h10l2 5 2 3v8H3v-8zM5 8h14M6 14h2m8 0h2M6 19v2m12-2v2"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M2 21v-4a7 7 0 0 1 14 0v4M16 4a3 3 0 0 1 0 6m2 3a6 6 0 0 1 4 6v2"/>',box:'<path d="m12 2 9 5v10l-9 5-9-5V7zM3 7l9 5 9-5m-9 5v10M7 4l10 6"/>',paper:'<path d="M5 2h10l4 4v16H5zM14 2v5h5M8 12h8m-8 4h8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',pin:'<path d="M19 9c0 6-7 13-7 13S5 15 5 9a7 7 0 0 1 14 0z"/><circle cx="12" cy="9" r="2"/>',copy:'<rect x="8" y="7" width="12" height="15" rx="1"/><path d="M16 7V2H3v15h5"/>',wheel:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="2"/><path d="m3 10 7 2m4 0 7-2m-9 4v7"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',bell:'<path d="M4 18h16l-2-3V9a6 6 0 0 0-12 0v6zM10 21h4"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z"/><path d="m8 12 3 3 5-6"/>'};
function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.paper}</svg>`}
function action(name,label,extra='',cls='text-btn'){return `<button class="${cls}" data-act="${name}" ${extra}>${label}</button>`}
function header(title,back='',right=''){return `<header class="header">${back?`<a class="icon-btn back" href="#${back}" aria-label="戻る">${icon('back')}</a>`:''}<h1>${esc(title)}</h1>${right}</header>`}
function nav(active){return `<nav class="nav" aria-label="メイン">${[['home','home','ホーム'],['calendar','calendar','予定'],['tasks','task','やること'],['operations','grid','運営'],['settings','settings','設定']].map(([r,i,t])=>`<a href="#${r}" class="${active===r?'active':''}">${icon(i)}<span>${t}</span></a>`).join('')}</nav>`}
function shell(title,active,body,back='',right=''){return header(title,back,right)+`<main class="content">${body}</main>`+nav(active)}
function entry(label,to,ico='paper',sub=''){return `<a class="row entry" href="#${to}">${icon(ico)}<div class="row-main"><div class="row-title">${esc(label)}</div>${sub?`<div class="row-sub">${esc(sub)}</div>`:''}</div>${icon('chev','chev')}</a>`}
function segments(items,val,act){return `<div class="segments">${items.map(([key,label])=>action(act,esc(label),`data-value="${key}"`,key===val?'active':'')).join('')}</div>`}
function go(route){if(location.hash==='#'+route)render();else location.hash=route}
function getRoute(){const p=location.hash.slice(1).split('/');return [p[0]||'home',p[1]||'',p[2]||'']}
const person=id=>state.people.find(p=>p.id===id);
const event=id=>state.events.find(p=>p.id===id);
const venue=id=>state.venues.find(p=>p.id===id);
function eventVenue(e){return venue(state.venueAssignments?.[e?.id]?.venueId??e?.venueId);}
const plan=id=>state.plans.find(p=>p.id===id);
const pName=id=>person(id)?.name||'未設定';
const oName=id=>state.operators.find(p=>p.id===id)?.name||'';
const aNames=ids=>ids?.length?ids.map(oName).join('・'):'幹部全員';
const participates=(eid,mid)=>state.attendance[eid+'|'+mid] ?? (person(mid)?.defaultOverride ?? person(mid)?.seniority==='below');
const participants=eid=>state.people.filter(p=>p.active&&participates(eid,p.id));
function dateTime(e){return `${jpDate(e.date)}${e.start?' '+e.start+(e.end?'–'+e.end:''):''}`}
function notifications(values=['P7D','P1D']){return `<div class="field"><span class="label">通知</span><div class="options">${[['P1M','1か月前'],['P7D','1週間前'],['P3D','3日前'],['P1D','1日前']].map(([v,t])=>`<label class="option"><input type="checkbox" name="notify" value="${v}" ${values.includes(v)?'checked':''}>${t}</label>`).join('')}</div></div>`}
function assigneeField(ids=[]){return `<div class="field"><span class="label">担当</span><details class="people-picker"><summary>${esc(aNames(ids))}</summary><div class="options">${state.operators.map(o=>`<label class="option"><input name="assignee" type="checkbox" value="${o.id}" ${ids.includes(o.id)?'checked':''}>${esc(o.name)}</label>`).join('')}</div></details></div>`}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span class="label">${esc(label)}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`}
function memoField(value=''){return `<label class="field"><span class="label">メモ</span><textarea name="memo">${esc(value)}</textarea></label>`}
function formShell(title,active,formName,inner,back,id=''){return header(title,back,`<button type="submit" class="text-btn" form="edit-form">保存</button>`)+`<main class="content"><form id="edit-form" data-form="${formName}" data-id="${id}">${inner}</form></main>`+nav(active)}
function taskRow(t,showAssignee=false){return `<div class="row">${action('task-toggle',t.done?icon('check'):'',`data-id="${t.id}" aria-label="${esc(t.title)}を${t.done?'未完了':'完了'}にする"`,'check '+(t.done?'on':''))}<a class="row-main" href="#task/${t.id}"><div class="row-title">${esc(t.title)}</div>${showAssignee?`<div class="row-sub">${esc(t.assignmentNeedsReview?'担当者を確認':aNames(t.assignees))}</div>`:''}</a><a class="deadline ${!t.done&&t.date<DEMO_TODAY?'red':''}" href="#task/${t.id}">${jpDate(t.date)}</a></div>`}
function renderHome(){const mine=state.tasks.filter(t=>!t.done&&(!t.assignees.length||t.assignees.includes(state.currentUser))).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return shell(state.group.name,'home',`<section class="section"><div class="section-head"><h2>お知らせ</h2><a class="small muted" href="#notices">すべて ${'›'}</a></div>${state.notices.filter(n=>!n.assignees.length||n.assignees.includes(state.currentUser)).slice(0,3).map(n=>`<a class="row" href="#notice/${n.id}"><span class="notice-date">${n.date.slice(5).replace('-','/')}</span><span class="row-main row-title">${esc(n.title)}</span></a>`).join('')||'<div class="empty">ありません</div>'}</section><section class="section"><div class="section-head"><h2>自分のやること</h2><a class="small muted" href="#tasks">すべて ›</a></div>${mine.map(t=>taskRow(t)).join('')||'<div class="empty">ありません</div>'}</section>`)}
function renderTasks(){const list=state.tasks.filter(t=>ui.taskTab==='done'?t.done:!t.done&&(ui.taskTab==='all'||!t.assignees.length||t.assignees.includes(state.currentUser))).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return shell('やること','tasks',segments([['self','自分'],['all','全体'],['done','完了']],ui.taskTab,'task-tab')+list.map(t=>taskRow(t,ui.taskTab!=='self')).join(''),'','<a class="icon-btn" href="#task-edit" aria-label="やることを追加">'+icon('plus')+'</a>')}
function renderTask(id){const t=state.tasks.find(t=>t.id===id);if(!t)return shell('やること','tasks','<p>見つかりません</p>','tasks');return shell('やること','tasks',`<h2 class="detail-title">${esc(t.title)}</h2><div class="detail-line">${icon('clock')}<span>${jpDate(t.date)}</span></div><div class="detail-line">${icon('people')}<span>${esc(t.assignmentNeedsReview?'担当者を確認':aNames(t.assignees))}</span></div>${t.memo?`<p>${esc(t.memo)}</p>`:''}${t.relatedEventId?`<a class="row" href="#event/${t.relatedEventId}"><span class="row-main">${esc(event(t.relatedEventId)?.title||'関連予定')}</span>${icon('chev','chev')}</a>`:''}<div class="form-actions">${action('task-toggle',t.done?'未完了に戻す':'完了',`data-id="${id}"`,'primary full')}</div>`,'tasks',`<a class="text-btn" href="#task-edit/${id}">編集</a>`)}
function renderTaskEdit(id,related=''){const t=state.tasks.find(t=>t.id===id)||{title:'',date:'2026-09-12',time:'23:59',assignees:[],memo:'',notifications:['P7D','P1D']};return formShell(id?'やることを編集':'やることを追加','tasks','task',field('タイトル','title',t.title,'text','required maxlength="100"')+assigneeField(t.assignees)+`<div class="inline-fields">${field('期限日','date',t.date,'date','required')}${field('期限時刻','time',t.time,'time','required')}</div>`+memoField(t.memo)+notifications(t.notifications)+`<input type="hidden" name="related" value="${esc(t.relatedEventId||related)}">`,id?'task/'+id:'tasks',id)}
function renderCalendar(){const y=ui.calendarYear,m=ui.calendarMonth;const first=new Date(y,m,1);const start=new Date(y,m,1-first.getDay());let cells='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const ds=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const items=state.events.filter(e=>e.date===ds&&(e.kind==='club'||ui.showExec)).map(e=>({title:e.title,cls:e.kind==='executive'?'exec':''}));if(ui.showExec)state.tasks.filter(t=>!t.done&&t.date===ds).forEach(t=>items.push({title:t.title,cls:'task'}));cells+=`<button class="day ${d.getMonth()!==m?'other':''}" data-act="open-day" data-date="${ds}"><span class="day-num">${d.getDate()}</span>${items.slice(0,2).map(e=>`<span class="event-chip ${e.cls}">${esc(e.title)}</span>`).join('')}${items.length>2?`<span class="small muted">＋${items.length-2}</span>`:''}</button>`}return shell('予定','calendar',`<div class="month-head">${action('month','‹','data-dir="-1"','icon-btn')}<h2>${y}年${m+1}月</h2>${action('month','›','data-dir="1"','icon-btn')}</div>${segments([['club','部活のみ'],['all','幹部予定も表示']],ui.showExec?'all':'club','calendar-filter')}<div class="calendar">${'日月火水木金土'.split('').map(x=>`<div class="weekday">${x}</div>`).join('')}${cells}</div><div class="calendar-footer">${action('calendar-export','画像')}</div>`,'','<a class="icon-btn" href="#event-edit" aria-label="予定を追加">'+icon('plus')+'</a>')}
function renderDay(date){let items=state.events.filter(e=>e.date===date&&(e.kind==='club'||ui.showExec)).map(e=>({type:'event',id:e.id,time:e.start||'',title:e.title,sub:e.kind==='club'?eventVenue(e)?.name||'':aNames(e.assignees)}));if(ui.showExec)state.tasks.filter(t=>!t.done&&t.date===date).forEach(t=>items.push({type:'task',id:t.id,time:t.time,title:t.title+'（締切）',sub:aNames(t.assignees)}));items.sort((a,b)=>a.time.localeCompare(b.time));return shell(jpDate(date,true),'calendar',items.map(x=>`<a class="day-item" href="#${x.type}/${x.id}"><span class="time-label">${x.time||'時刻なし'}</span><div><div class="row-title">${esc(x.title)}</div><div class="row-sub">${esc(x.sub)}</div></div></a>`).join('')||'<div class="empty">予定はありません</div>','calendar',`<a class="icon-btn" href="#event-edit//${date}" aria-label="予定を追加">${icon('plus')}</a>`)}
function renderEvent(id){const e=event(id);if(!e)return shell('予定','calendar','見つかりません','calendar');let extra='';if(e.kind==='club'){const ps=participants(id);extra='<hr class="rule"><h2>参加者</h2>'+[6,5,4,3,2,1].map(g=>{let a=ps.filter(p=>p.grade===g);return a.length?`<h3 class="grade">${g}年</h3><div class="name-list">${a.map(p=>`<span>${esc(p.name)}</span>`).join('')}</div>`:''}).join('')}else extra=`<div class="detail-line">${icon('people')}<span>${esc(e.assignmentNeedsReview?'担当者を確認':aNames(e.assignees))}</span></div>${e.memo?`<p>${esc(e.memo)}</p>`:''}<hr class="rule"><a class="text-btn" href="#task-add-from/${e.id}">やることを追加</a>`;return shell(e.kind==='club'?'部活予定':'幹部予定','calendar',`<h2 class="detail-title">${esc(e.title)}</h2><div class="detail-line">${icon('calendar')}<span>${jpDate(e.date,true)}</span></div>${e.start?`<div class="detail-line">${icon('clock')}<span>${e.start}${e.end?'–'+e.end:''}</span></div>`:''}${e.venueId?`<div class="detail-line">${icon('pin')}<span>${esc(eventVenue(e)?.name||'体育館未設定')}</span></div>`:''}${extra}`,'calendar',`<a class="text-btn" href="#event-edit/${id}">編集</a>`)}
function renderEventEdit(id,date){const e=event(id)||{title:'',date:date||'2026-09-12',start:'',end:'',kind:'club',venueId:'',assignees:[],memo:''};return formShell(id?'予定を編集':'予定を追加','calendar','event',`<label class="field"><span class="label">予定</span><select name="kind"><option value="club" ${e.kind==='club'?'selected':''}>部活予定</option><option value="executive" ${e.kind==='executive'?'selected':''}>幹部予定</option></select></label>`+field('タイトル','title',e.title,'text','required')+field('日付','date',e.date,'date','required')+`<div class="inline-fields">${field('開始','start',e.start,'time')}${field('終了','end',e.end,'time')}</div><label class="field"><span class="label">体育館</span><select name="venue"><option value="">未設定</option>${state.venues.map(v=>`<option value="${v.id}" ${e.venueId===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label>`+assigneeField(e.assignees)+memoField(e.memo)+notifications(e.notifications||state.settings.reminders),id?'event/'+id:'calendar',id)}
function renderNotices(){return shell('お知らせ','home',state.notices.filter(n=>!n.assignees.length||n.assignees.includes(state.currentUser)).map(n=>`<a class="row" href="#notice/${n.id}"><div class="row-main"><div class="row-title">${esc(n.title)}</div><div class="row-sub">${jpDate(n.date)}</div></div>${icon('chev','chev')}</a>`).join(''),'home',`<a class="icon-btn" href="#notice-edit" aria-label="投稿を追加">${icon('plus')}</a>`)}
function renderNotice(id){const n=state.notices.find(n=>n.id===id);if(!n)return shell('お知らせ','home','見つかりません','notices');return shell('お知らせ','home',`<h2 class="detail-title">${esc(n.title)}</h2><p class="row-sub">${esc(n.author)}　${jpDate(n.date)}</p><p style="margin-top:24px;line-height:1.9;white-space:pre-wrap">${esc(n.body)}</p>`,'notices',`<a class="text-btn" href="#notice-edit/${id}">編集</a>`)}
function renderNoticeEdit(id){const n=state.notices.find(n=>n.id===id)||{title:'',body:'',assignees:[],notify:true};return formShell(id?'お知らせを編集':'お知らせを追加','home','notice',field('タイトル','title',n.title,'text','required')+`<label class="field"><span class="label">本文</span><textarea name="body" required>${esc(n.body)}</textarea></label>`+assigneeField(n.assignees).replace('<span class="label">担当</span>','<span class="label">対象</span>')+`<label class="option"><input type="checkbox" name="push" ${n.notify?'checked':''}>通知する</label>`,'notices',id)}
function renderOperations(){return shell('運営','operations',entry('出欠','attendance','people')+entry('配車','carpools','car')+entry('体育館','venues','calendar')+entry('練習メニュー','practice','paper')+entry('備品','equipment','box'))}
function clubEvents(){return state.events.filter(e=>e.kind==='club').sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start))}
function renderAttendance(){let body=segments([['date','日程から'],['member','部員から']],ui.attendanceMode,'attendance-mode');if(ui.attendanceMode==='date'){const e=event(ui.attendanceEvent)||clubEvents()[0];body+=action('pick-attendance-event',`<div><strong>${jpDate(e.date)}</strong><div class="row-sub">${e.start||''}${e.end?'–'+e.end:''}　${esc(eventVenue(e)?.name||'')}</div></div>${icon('chev','chev')}`,'','selector');body+='<div class="attendance-people-grid">'+[6,5,4,3,2,1].map(g=>{const ps=state.people.filter(p=>p.active&&p.grade===g);return ps.length?`<h3 class="grade attendance-grade">${g}年</h3>`+ps.map(p=>`<button class="row" data-act="attendance-toggle" data-eid="${e.id}" data-mid="${p.id}"><span class="row-main">${esc(p.name)}</span><span class="attendance-state ${participates(e.id,p.id)?'yes':''}">${participates(e.id,p.id)?'参加':'不参加'}</span></button>`).join(''):''}).join('')+'</div>'}else{const p=person(ui.attendanceMember);body+=action('pick-attendance-member',`<div><strong>${esc(p.name)}</strong><div class="row-sub">${p.grade}年</div></div>${icon('chev','chev')}`,'','selector');body+=attendanceMemberMonths(p)}return shell('出欠','operations',body,'operations')}
// 配車ドメイン。UIとPNGはこの同じ状態を参照する。
function legOf(p){return p.linked?'outbound':ui.leg}
function carPeople(c){return [...(c.driver?[c.driver]:[]),...c.riders]}
function assigned(p,leg){return new Set(p.legs[leg].flatMap(carPeople))}
function needs(p,leg,mid){const v=p.need[leg]?.[mid];return v===undefined?person(mid)?.seniority==='below':v}
function missing(p,leg){const a=assigned(p,leg);return participants(p.eventId).filter(m=>needs(p,leg,m.id)&&!a.has(m.id))}
function invalid(p){const errors=[];for(const leg of ['outbound','return']){if(!p.enabled[leg])continue;const seen=new Set();for(const c of p.legs[leg]){if(!c.driver)errors.push('運転者を指定');if(carPeople(c).length>4||c.riders.length>3)errors.push('4人まで');for(const mid of carPeople(c)){if(seen.has(mid))errors.push('重複しています');seen.add(mid);if(!participates(p.eventId,mid))errors.push('不参加の人が含まれています')}}if(missing(p,leg).length)errors.push(`${leg==='outbound'?'行き':'帰り'}：未配車${missing(p,leg).length}人`)}return [...new Set(errors)]}
function moveMember(planId,mid,dest,leg=undefined){const p=plan(planId);if(!p)return {ok:false,error:'配車なし'};leg=leg||legOf(p);if(!p.legs[leg]||!dest)return {ok:false,error:'移動先なし'};if(!person(mid)?.active)return {ok:false,error:'部員なし'};if(!participates(p.eventId,mid))return {ok:false,error:'参加者から選択してください'};const cars=clone(p.legs[leg]);cars.forEach(c=>{if(c.driver===mid)c.driver=null;c.riders=c.riders.filter(x=>x!==mid)});const target=cars.find(c=>c.id===dest.carId);if(dest.kind==='new'){cars.push({id:UID(),pickup:dest.pickup||person(mid).pickup,driver:mid,riders:[]})}else if(dest.kind==='driver'){if(!target)return {ok:false,error:'車なし'};target.driver=mid;}else if(dest.kind==='passenger'){if(!target)return {ok:false,error:'車なし'};if(target.riders.length>=3||carPeople(target).length>=4)return {ok:false,error:'4人まで'};target.riders.push(mid);}else if(dest.kind!=='pool'){return {ok:false,error:'移動先なし'}}
 checkpoint();p.legs[leg]=cars;if(p.linked)p.legs[leg==='outbound'?'return':'outbound']=clone(cars);p.status='draft';p.version++;ui.selectedPerson=null;persist();return {ok:true};}
function copyPlan(sourceId,targetId){const src=plan(sourceId),dst=plan(targetId);if(!src||!dst||src===dst)return {ok:false};checkpoint();let removed=new Set();for(const leg of ['outbound','return']){dst.legs[leg]=src.legs[leg].map(c=>{const valid=mid=>{const yes=participates(dst.eventId,mid)&&person(mid)?.active;if(!yes)removed.add(mid);return yes};return {id:UID(),pickup:c.pickup,driver:c.driver&&valid(c.driver)?c.driver:null,riders:c.riders.filter(valid)}});dst.need[leg]={};dst.enabled[leg]=src.enabled[leg]}dst.linked=src.linked;dst.status='draft';dst.unitYen=state.settings.unitYen;dst.sourcePlanId=src.id;dst.version++;persist();return {ok:true,removed:removed.size};}
function addPlan(eid){const exists=state.plans.find(p=>p.eventId===eid);if(exists)return exists;const p={id:UID(),eventId:eid,linked:true,legs:{outbound:[],return:[]},enabled:{outbound:true,return:true},need:{outbound:{},return:{}},status:'draft',version:1,unitYen:state.settings.unitYen};state.plans.unshift(p);persist();return p;}
function renderCarpools(){const ps=state.plans.filter(p=>ui.carTab==='history'?event(p.eventId)?.date<DEMO_TODAY:event(p.eventId)?.date>=DEMO_TODAY).sort((a,b)=>event(a.eventId).date.localeCompare(event(b.eventId).date));return shell('配車','operations',segments([['future','今後'],['history','履歴']],ui.carTab,'car-tab')+ps.map(p=>{const e=event(p.eventId);return `<a class="row" href="#car/${p.id}"><div class="row-main"><div class="row-title">${jpDate(e.date)}　${esc(eventVenue(e)?.name||e.title)}</div><div class="row-sub">${e.start||''}${e.end?'–'+e.end:''}</div></div>${p.status==='draft'?'<span class="small muted">下書き</span>':''}${icon('chev','chev')}</a>`}).join('')+`<hr class="rule">${entry('月次精算','settlement','paper')}`,'operations',`<a class="icon-btn" href="#car-add" aria-label="配車表を追加">${icon('plus')}</a>`)}
function renderCarAdd(){return shell('部活予定を選択','operations',clubEvents().filter(e=>e.date>=DEMO_TODAY).map(e=>`<button class="row" data-act="car-create" data-id="${e.id}"><div class="row-main"><div class="row-title">${jpDate(e.date)}　${esc(eventVenue(e)?.name||'体育館未設定')}</div><div class="row-sub">${e.start||''}${e.end?'–'+e.end:''}　${esc(e.title)}</div></div>${icon('chev','chev')}</button>`).join(''),'carpools')}
function memberChip(mid,needed=false,driver=false){const m=person(mid);return `<button class="person ${needed?'needed':''} ${ui.selectedPerson===mid?'selected':''}" data-act="person-select" data-person="${mid}" title="${esc(m?.name)}"><span class="person-name">${esc(m?.name)}</span><span class="grip" aria-hidden="true">⠿</span></button>`}
function renderCar(id){const p=plan(id);if(!p)return shell('配車','operations','見つかりません','carpools');const e=event(p.eventId),leg=legOf(p),cars=p.legs[leg],used=assigned(p,leg),ps=participants(e.id).filter(m=>!used.has(m.id));const needed=ps.filter(m=>needs(p,leg,m.id)),optional=ps.filter(m=>!needs(p,leg,m.id));const groupHTML=(members,red)=>[6,5,4,3,2,1].map(g=>{const a=members.filter(m=>m.grade===g);return a.length?`<div class="member-grade">${g}年</div>`+a.map(m=>memberChip(m.id,red)).join(''):''}).join('');let left='';for(const [key,label] of [['university','大学配車'],['station','駅配車']]){left+=`<div class="zone-title">${label}</div>`+cars.filter(c=>c.pickup===key).map(c=>`<section class="car" data-car="${c.id}"><div class="car-top"><span class="small ${!c.driver?'red':'muted'}">${!c.driver?'運転者未設定':''}</span><span class="car-count">${carPeople(c).length}/4</span>${action('car-menu',icon('more'),`data-id="${c.id}" aria-label="車の操作"`,'tiny-icon')}</div><div class="driver-slot" data-drop="driver" data-car-id="${c.id}">${icon('wheel')}${c.driver?memberChip(c.driver,false,true):action('drop-tap','運転者',`data-drop="driver" data-car-id="${c.id}"`,'text-btn')}</div>${c.riders.map(mid=>memberChip(mid)).join('')}${c.riders.length<3?action('drop-tap','＋',`data-drop="passenger" data-car-id="${c.id}" aria-label="同乗者を追加"`,'empty-seat'):''}</section>`).join('')+action('new-car',`${icon('plus')}車`, `data-drop="new" data-pickup="${key}"`,'new-car')}
 const right=`<div class="zone-title ${needed.length?'missing-title':''}" data-drop="pool">${needed.length?'未配車 '+needed.length:'未配車 0'}</div><div class="unassigned-target" data-drop="pool">${groupHTML(needed,true)}</div><details open><summary>配車不要${optional.length?' '+optional.length:''}</summary>${groupHTML(optional,false)}</details>`;
 return header('配車','carpools',action('register-car','登録',`data-id="${id}"`,'text-btn'))+`<div class="car-meta"><strong>${jpDate(e.date)}　${esc(eventVenue(e)?.name||'体育館未設定')}</strong></div><div class="car-toolbar">${p.linked?action('split-car','往復 ▾',`data-id="${id}"`,'secondary'):segments([['outbound','行き'],['return','帰り']],leg,'car-leg')}${action('copy-open','コピー',`data-id="${id}"`)}<a class="text-btn" href="#car-table/${id}">表</a>${action('car-options',icon('more'),`data-id="${id}" aria-label="配車設定"`,'tiny-icon')}</div><div class="car-workspace"><div class="scroll-pane cars-pane">${left}</div><aside class="scroll-pane member-pane" aria-label="未配車の部員">${right}</aside></div>`+nav('operations')}
function tableParts(p){const sections=[];const legs=p.linked?['outbound']:['outbound','return'];for(const leg of legs){if(!p.enabled[leg])continue;for(const [k,label] of [['university','大学配車'],['station','駅配車']]){const cs=p.legs[leg].filter(c=>c.pickup===k&&carPeople(c).length);if(cs.length)sections.push({label,leg,legLabel:p.linked?'往復':leg==='outbound'?'行き':'帰り',cars:cs})}}return sections}
function tableHtml(section){const rows=Math.max(1,...section.cars.map(c=>c.riders.length));return `<div class="ride-group">${section.label}${section.legLabel==='往復'?'':'（'+section.legLabel+'）'}</div><div class="table-scroll"><table class="ride-table"><thead><tr>${section.cars.map(c=>`<th scope="col">${esc(pName(c.driver))}</th>`).join('')}</tr></thead><tbody>${Array.from({length:rows},(_,i)=>`<tr>${section.cars.map(c=>`<td>${c.riders[i]?esc(pName(c.riders[i])):''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function renderTable(id){const p=plan(id),e=event(p?.eventId);if(!p||!e)return '';const errors=invalid(p);return shell('配車表','operations',`${errors.length?`<div class="warning no-print">${esc(errors.join('／'))}</div>`:''}<div id="share-table"><h2 class="ride-title">${jpDate(e.date)} ${esc(eventVenue(e)?.name||e.title)}${p.linked?'（往復）':''}</h2>${tableParts(p).map(tableHtml).join('')}</div>`,'car/'+id,action('export-car','共有',`data-id="${id}" ${errors.length?'disabled':''}`,'primary'))}
function settlementLines(month='2026-09'){const map=new Map();for(const p of state.plans){const e=event(p.eventId);if(p.status!=='registered'||e.date>=DEMO_TODAY||!e.date.startsWith(month))continue;for(const leg of ['outbound','return']){if(!p.enabled[leg])continue;for(const c of p.legs[leg]){if(!c.driver)continue;for(const rider of c.riders){if(rider===c.driver)continue;const key=rider+'|'+c.driver;const x=map.get(key)||{rider,driver:c.driver,count:0,amount:0,details:[]};x.count++;x.amount+=Number.isFinite(p.unitYen)?p.unitYen:0;x.unset=x.unset||!Number.isFinite(p.unitYen);x.details.push({date:e.date,leg,amount:p.unitYen,planId:p.id});map.set(key,x)}}}}return [...map.values()].sort((a,b)=>pName(a.driver).localeCompare(pName(b.driver),'ja'))}
function renderSettlement(){const lines=settlementLines();return shell('月次精算','operations',`<div class="month-head"><span></span><h2>2026年9月</h2><span></span></div>${lines.map(l=>`<button class="row" data-act="settlement-detail" data-rider="${l.rider}" data-driver="${l.driver}"><span class="row-main">${esc(pName(l.rider))} → ${esc(pName(l.driver))}</span><strong>${l.unset?'単価未設定':money(l.amount)}</strong>${icon('chev','chev')}</button>`).join('')||'<p class="empty">集計対象はありません</p>'}<div class="row"><span class="row-main muted">合計</span><strong>${money(lines.reduce((s,l)=>s+l.amount,0))}</strong></div><p class="note" style="margin-top:18px">登録した配車に基づく集計です。</p>`,'carpools')}
function renderVenues(){return shell('体育館','operations',state.venues.map(v=>`<a class="row" href="#venue-edit/${v.id}"><div class="row-main"><div class="row-title">${esc(v.name)}</div><div class="row-sub">${v.courts}面${v.memo?'　'+esc(v.memo):''}</div></div>${icon('chev','chev')}</a>`).join(''),'operations',`<a class="icon-btn" href="#venue-edit" aria-label="体育館を追加">${icon('plus')}</a>`)}
function renderVenueEdit(id){const v=venue(id)||{name:'',courts:4,memo:''};return formShell('体育館','operations','venue',field('体育館名','name',v.name,'text','required')+field('コート数','courts',v.courts,'number','required min="1" max="30"')+memoField(v.memo),'venues',id)}
function renderEquipment(){return shell('備品','operations',state.equipment.map(x=>`<div class="row"><a class="row-main" href="#equipment-edit/${x.id}"><div class="row-title ${x.threshold!==null&&x.quantity<=x.threshold?'red':''}">${esc(x.name)}</div>${x.memo?`<div class="row-sub">${esc(x.memo)}</div>`:''}</a><div class="quantity">${action('stock','−',`data-id="${x.id}" data-delta="-1" aria-label="${esc(x.name)}を減らす" ${x.quantity<=0?'disabled':''}`,'')}<a class="num" href="#equipment-edit/${x.id}">${x.quantity}<small> ${esc(x.unit)}</small></a>${action('stock','＋',`data-id="${x.id}" data-delta="1" aria-label="${esc(x.name)}を増やす"`,'')}</div></div>`).join(''),'operations',`<a class="icon-btn" href="#equipment-edit" aria-label="備品を追加">${icon('plus')}</a>`)}
function renderEquipmentEdit(id){const x=state.equipment.find(x=>x.id===id)||{name:'',quantity:0,unit:'個',memo:'',threshold:null};return formShell('備品','operations','equipment',field('備品名','name',x.name,'text','required')+`<div class="inline-fields">${field('数量','quantity',x.quantity,'number','min="0" required')}${field('単位','unit',x.unit,'text','required')}</div>`+memoField(x.memo)+`<details><summary class="muted small">不足の目安</summary><div style="height:12px"></div>${field('数量','threshold',x.threshold??'','number','min="0"')}</details>`,'equipment',id)}
function renderSettings(){return shell('設定','settings',`<div class="section"><h2>${esc(state.group.name)}</h2><p class="row-sub">細川</p></div>`+entry('グループ','group','people')+entry('部員','members','people')+entry('運営メンバー','operators','people')+entry('担当・権限','roles','shield')+entry('通知','notification-settings','bell')+entry('配車設定','car-settings','car')+`<hr class="rule"><p class="note">UI試作・この端末のみ保存<br>端末内デモ。共有はサーバー版で利用します。</p><div class="form-actions">${action('reset','サンプルをリセット','','secondary')}</div>`)}
function renderMembers(){return shell('部員','settings',segments([['all','全員'],['above','幹部上'],['below','幹部以下']],ui.memberFilter,'member-filter')+state.people.filter(p=>p.active&&(ui.memberFilter==='all'||p.seniority===ui.memberFilter)).sort((a,b)=>b.grade-a.grade).map(p=>`<a class="row" href="#member-edit/${p.id}"><div class="row-main"><div class="row-title">${esc(p.name)} <span class="muted small">${p.grade}年</span></div><div class="row-sub">${p.seniority==='above'?'幹部上':'幹部以下'}　${p.pickup==='university'?'大学配車':'駅配車'}</div></div>${icon('chev','chev')}</a>`).join(''),'settings',`<a class="icon-btn" href="#member-edit" aria-label="部員を追加">${icon('plus')}</a>`)}
function renderMemberEdit(id){const p=person(id)||{name:'',grade:1,seniority:'below',pickup:'university',memo:'',defaultOverride:null};return formShell('部員','settings','member',field('名前','name',p.name,'text','required')+`<label class="field"><span class="label">学年</span><select name="grade">${[1,2,3,4,5,6].map(g=>`<option value="${g}" ${p.grade===g?'selected':''}>${g}年</option>`).join('')}</select></label><label class="field"><span class="label">区分</span><select name="seniority"><option value="below" ${p.seniority==='below'?'selected':''}>幹部以下</option><option value="above" ${p.seniority==='above'?'selected':''}>幹部上</option></select></label><label class="field"><span class="label">配車</span><select name="pickup"><option value="university" ${p.pickup==='university'?'selected':''}>大学配車</option><option value="station" ${p.pickup==='station'?'selected':''}>駅配車</option></select></label>`+memoField(p.memo)+`<details><summary class="muted small">通常の参加</summary><select name="defaultOverride" style="margin-top:10px"><option value="default" ${p.defaultOverride===null?'selected':''}>区分に合わせる</option><option value="true" ${p.defaultOverride===true?'selected':''}>参加</option><option value="false" ${p.defaultOverride===false?'selected':''}>不参加</option></select></details>`,'members',id)}
function renderRoles(){return shell('担当・権限','settings',Object.entries(state.roles).map(([name,ids])=>`<button class="row" data-act="role-edit" data-name="${esc(name)}"><span class="row-main">${esc(name)}</span><span class="small">${esc(aNames(ids))}</span>${icon('chev','chev')}</button>`).join('')+`<hr class="rule"><p class="note">運営メンバーは閲覧、担当者は編集。</p>`,'settings')}
function renderOperators(){return shell('運営メンバー','settings',state.operators.map(o=>`<div class="row"><span class="row-main">${esc(o.name)}</span><span class="muted small">${o.id==='u1'?'オーナー':'運営'}</span></div>`).join('')+`<div class="form-actions">${action('demo-invite','招待','','secondary full')}</div>`,'settings')}
function renderGroup(){return formShell('グループ','settings','group',field('グループ名','name',state.group.name,'text','required')+`<div class="row"><span>オーナー</span><span class="row-end">細川</span></div>`,'settings')}
function renderNotificationSettings(){return formShell('通知','settings','notifications',`<div class="field"><div class="row"><span class="row-main">この端末の通知</span>${action('demo-notification','設定')}</div></div>`+notifications(state.settings.reminders)+`<p class="note">時刻なし予定は9:00を基準にします。</p>`,'settings')}
function renderCarSettings(){return formShell('配車設定','settings','carsettings',field('片道1回の料金（円）','unitYen',state.settings.unitYen??'','number','min="0" step="1"')+`<p class="note">往復は2回。サンプルでは300円。</p><hr class="rule">`+notifications(state.settings.reminders),'settings')}
function renderPractice(){const e=event('e1');return shell('練習メニュー','operations',`<a class="selector" href="#event/e1"><div><strong>${jpDate(e.date)}　${esc(eventVenue(e).name)}</strong><div class="row-sub">${participants(e.id).length}人　${eventVenue(e).courts}面　${e.start}–${e.end}</div></div>${icon('chev','chev')}</a><div style="height:16px"></div>`+entry('メニュー表作成','legacy/create','paper')+entry('保存したメニュー表','practice-saved','paper')+entry('メニュー追加','legacy/add','plus')+entry('メニュー一覧','legacy/list','paper')+`<p class="note" style="margin-top:22px">過去版HTMLの動作参照。最新実装との接続は別工程です。</p>`,'operations')}
function renderPracticeSaved(){return shell('保存したメニュー表','operations','<p class="note">この過去版HTMLには保存表一覧がありません。最新ソース確認後に接続します。</p>','practice')}
function renderLegacy(){return renderPractice()}
function render(){const [r,id,extra]=getRoute();document.body.classList.toggle('wide',r==='car');let html='';switch(r){case'home':html=renderHome();break;case'tasks':html=renderTasks();break;case'task':html=renderTask(id);break;case'task-edit':html=renderTaskEdit(id);break;case'task-add-from':html=renderTaskEdit('',id);break;case'calendar':html=renderCalendar();break;case'day':html=renderDay(id);break;case'event':html=renderEvent(id);break;case'event-edit':html=renderEventEdit(id,extra);break;case'notices':html=renderNotices();break;case'notice':html=renderNotice(id);break;case'notice-edit':html=renderNoticeEdit(id);break;case'operations':html=renderOperations();break;case'attendance':html=renderAttendance();break;case'carpools':html=renderCarpools();break;case'car-add':html=renderCarAdd();break;case'car':html=renderCar(id);break;case'car-table':html=renderTable(id);break;case'settlement':html=renderSettlement();break;case'venues':html=renderVenues();break;case'venue-edit':html=renderVenueEdit(id);break;case'equipment':html=renderEquipment();break;case'equipment-edit':html=renderEquipmentEdit(id);break;case'settings':html=renderSettings();break;case'members':html=renderMembers();break;case'member-edit':html=renderMemberEdit(id);break;case'roles':html=renderRoles();break;case'operators':html=renderOperators();break;case'group':html=renderGroup();break;case'notification-settings':html=renderNotificationSettings();break;case'car-settings':html=renderCarSettings();break;case'practice':html=renderPractice();break;case'practice-saved':html=renderPracticeSaved();break;case'legacy':html=renderLegacy(id);break;default:html=renderHome()};const scrolls=[...document.querySelectorAll('.scroll-pane')].map(e=>e.scrollTop);document.getElementById('app').innerHTML=html;document.querySelectorAll('.scroll-pane').forEach((e,i)=>e.scrollTop=scrolls[i]||0);if(r==='legacy')mountLegacy(id);}
function modal(title,content){document.getElementById('modal-root').innerHTML=`<div class="modal-bg" data-act="close-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2 class="modal-title">${esc(title)}</h2>${action('close-modal','×','aria-label="閉じる"','modal-close')}</div>${content}</section></div>`}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function destinationFrom(el){if(!el)return null;return {kind:el.dataset.drop,carId:el.dataset.carId,pickup:el.dataset.pickup}}
function performMove(mid,dest){const [r,id]=getRoute();if(r!=='car')return;const result=moveMember(id,mid,dest);render();toast(result.ok?'移動しました':result.error,result.ok)}
function personMenu(mid){const [r,id]=getRoute();const p=plan(id);if(!p)return;const leg=legOf(p);modal(pName(mid),`<div class="chips"><span class="chip">${person(mid).grade}年</span><span class="chip">${person(mid).pickup==='university'?'大学配車':'駅配車'}</span></div><div class="row">${action('need-toggle',needs(p,leg,mid)?'この片道は配車不要':'この片道は配車必要',`data-mid="${mid}"`,'text-btn')}</div>${action('assign-choice','未配車へ戻す',`data-mid="${mid}" data-kind="pool"`,'row')}${p.legs[leg].map(c=>`<div class="row"><span class="row-main">${esc(pName(c.driver))}</span>${action('assign-choice','運転',`data-mid="${mid}" data-kind="driver" data-car-id="${c.id}"`)}${action('assign-choice','同乗',`data-mid="${mid}" data-kind="passenger" data-car-id="${c.id}"`)}</div>`).join('')}`)}
function copyModal(id){modal('配車をコピー',state.plans.filter(p=>p.id!==id).map(p=>{const e=event(p.eventId);return `<button class="row" data-act="copy-apply" data-source="${p.id}" data-target="${id}"><div class="row-main"><div>${jpDate(e.date)} ${esc(eventVenue(e)?.name||e.title)}</div><div class="row-sub">${p.legs.outbound.length}台</div></div>${icon('chev','chev')}</button>`}).join('')||'<div class="empty">コピー元がありません</div>')}
function carOptions(id){const p=plan(id);modal('配車設定',`<div class="row"><span class="row-main">往復同じ</span>${action(p.linked?'split-apply':'merge-apply',p.linked?'分ける':'まとめる',`data-id="${id}"`)}</div>${!p.linked?`<div class="row"><span class="row-main">${ui.leg==='outbound'?'行き':'帰り'}</span>${action('leg-enabled',p.enabled[ui.leg]?'対象外にする':'対象にする',`data-id="${id}"`)}</div>`:''}<div class="row"><span class="row-main">通知</span><span class="small muted">グループ設定</span></div><p class="note">個別の料金・回数は月次精算の明細から調整できます。</p>`)}
let lastDragUntil=0;
document.addEventListener('click',ev=>{if(Date.now()<lastDragUntil&&ev.target.closest('[data-person]'))return;const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;const d=b.dataset;const [r,id]=getRoute();switch(d.act){case'undo':if(undoState){state=undoState;undoState=null;persist();render();toast('元に戻しました')}break;case'task-tab':ui.taskTab=d.value;render();break;case'task-toggle':{const t=state.tasks.find(t=>t.id===d.id);if(t){checkpoint();t.done=!t.done;persist();render();toast(t.done?'完了しました':'未完了に戻しました',true)}}break;case'calendar-filter':ui.showExec=d.value==='all';render();break;case'month':ui.calendarMonth+=Number(d.dir);if(ui.calendarMonth<0){ui.calendarMonth=11;ui.calendarYear--}if(ui.calendarMonth>11){ui.calendarMonth=0;ui.calendarYear++}render();break;case'open-day':go('day/'+d.date);break;case'calendar-export':imagePreview(drawCalendar(false),'予定表.png');break;case'attendance-mode':ui.attendanceMode=d.value;render();break;case'attendance-toggle':checkpoint();state.attendance[d.eid+'|'+d.mid]=!participates(d.eid,d.mid);if(ctx.mode==='demo')ClubDomain.reconcileAbsent(state,[d.eid]);ui.selectedPerson=null;persist();render();break;case'pick-attendance-event':modal('部活予定',clubEvents().filter(e=>e.date>=DEMO_TODAY&&e.date<=ClubDomain.addMonths(DEMO_TODAY,3)).map(e=>action('set-attendance-event',`${jpDate(e.date)}　${esc(eventVenue(e)?.name||'')}`,`data-id="${e.id}"`,'row')).join(''));break;case'set-attendance-event':ui.attendanceEvent=d.id;closeModal();render();break;case'pick-attendance-member':modal('部員',state.people.map(p=>action('set-attendance-member',`${esc(p.name)}　<span class="small muted">${p.grade}年</span>`,`data-id="${p.id}"`,'row')).join(''));break;case'set-attendance-member':ui.attendanceMember=d.id;closeModal();render();break;case'car-tab':ui.carTab=d.value;render();break;case'car-create':{const p=addPlan(d.id);ui.leg='outbound';ui.selectedPerson=null;go('car/'+p.id)}break;case'person-select':{const driverZone=b.closest('[data-drop="driver"]');if(ui.selectedPerson&&ui.selectedPerson!==d.person&&driverZone){performMove(ui.selectedPerson,destinationFrom(driverZone))}else if(ui.selectedPerson===d.person){personMenu(d.person)}else{ui.selectedPerson=d.person;render()}}break;case'drop-tap':if(ui.selectedPerson)performMove(ui.selectedPerson,destinationFrom(b));else toast('右の名前を選択');break;case'new-car':if(ui.selectedPerson)performMove(ui.selectedPerson,{kind:'new',pickup:d.pickup});else{checkpoint();const p=plan(id),leg=legOf(p);p.legs[leg].push({id:UID(),pickup:d.pickup,driver:null,riders:[]});if(p.linked)p.legs.return=clone(p.legs.outbound);p.status='draft';persist();render()}break;case'car-menu':{const p=plan(id),c=p.legs[legOf(p)].find(c=>c.id===d.id);modal(c.driver?pName(c.driver):'車',`${action('delete-car','車を削除',`data-id="${c.id}"`,'row danger-button')}`)}break;case'delete-car':{const p=plan(id),leg=legOf(p);if(!confirm('この車を削除し、部員を候補に戻しますか？'))break;checkpoint();p.legs[leg]=p.legs[leg].filter(c=>c.id!==d.id);if(p.linked)p.legs.return=clone(p.legs.outbound);p.status='draft';persist();closeModal();render();toast('車を削除しました',true)}break;case'copy-open':copyModal(d.id);break;case'copy-apply':if(confirm('現在の配置をコピー元の配置で置き換えますか？')){const res=copyPlan(d.source,d.target);closeModal();render();toast(`コピーしました${res.removed?'・不参加'+res.removed+'人を除外':''}`,true)}break;case'split-car':modal('往復',action('split-apply','行き・帰りを分ける',`data-id="${d.id}"`,'row'));break;case'split-apply':{checkpoint();const p=plan(d.id);p.linked=false;ui.leg='outbound';persist();closeModal();render()}break;case'merge-apply':{const p=plan(d.id);if(confirm(`${ui.leg==='outbound'?'行き':'帰り'}の配置を往復に適用しますか？`)){checkpoint();p.legs.outbound=clone(p.legs[ui.leg]);p.legs.return=clone(p.legs[ui.leg]);p.need.outbound=clone(p.need[ui.leg]);p.need.return=clone(p.need[ui.leg]);p.enabled={outbound:true,return:true};p.linked=true;ui.leg='outbound';p.status='draft';persist();closeModal();render()}}break;case'car-leg':ui.leg=d.value;ui.selectedPerson=null;render();break;case'car-options':carOptions(d.id);break;case'leg-enabled':{const p=plan(d.id);p.enabled[ui.leg]=!p.enabled[ui.leg];p.status='draft';persist();closeModal();render();toast(p.enabled[ui.leg]?'対象にしました':'この片道は精算対象外です')}break;case'need-toggle':{checkpoint();const p=plan(id),leg=legOf(p);p.need[leg][d.mid]=!needs(p,leg,d.mid);if(p.linked)p.need.return=clone(p.need.outbound);p.status='draft';persist();closeModal();render()}break;case'assign-choice':closeModal();performMove(d.mid,{kind:d.kind,carId:d.carId});break;case'register-car':{const p=plan(d.id),errors=invalid(p);if(errors.length){toast(errors[0]+'・下書きを保存');persist();render()}else{p.status='registered';persist();go('car-table/'+p.id);toast('登録しました')}}break;case'export-car':exportCar(d.id);break;case'settlement-detail':{const l=settlementLines().find(x=>x.rider===d.rider&&x.driver===d.driver);modal(`${pName(l.rider)} → ${pName(l.driver)}`,`<div class="overview-amount">${l.unset?'単価未設定':money(l.amount)}</div><div style="height:12px"></div>${l.details.map(x=>`<a class="row" href="#car-table/${x.planId}" data-act="close-modal"><span class="row-main">${jpDate(x.date)} ${x.leg==='outbound'?'行き':'帰り'}</span><span>${Number.isFinite(x.amount)?money(x.amount):'未設定'}</span></a>`).join('')}`)}break;case'stock':{const x=state.equipment.find(x=>x.id===d.id);checkpoint();x.quantity=Math.max(0,x.quantity+Number(d.delta));persist();render()}break;case'member-filter':ui.memberFilter=d.value;render();break;case'role-edit':modal(d.name,`<form data-form="role" data-name="${esc(d.name)}"><div class="options">${state.operators.map(o=>`<label class="option"><input type="checkbox" name="assignee" value="${o.id}" ${(state.roles[d.name]||[]).includes(o.id)?'checked':''}>${esc(o.name)}</label>`).join('')}</div><div class="form-actions"><button class="primary full" type="submit">保存</button></div></form>`);break;case'demo-notification':toast('UI試作では通知送信しません');break;case'demo-invite':toast('招待は認証・共有DBの接続後に有効になります');break;case'reset':if(confirm('この端末のサンプルを初期状態に戻しますか？')){state=seed();persist();ui.leg='outbound';go('home');toast('リセットしました')}break;case'close-modal':closeModal();break;case'close-backdrop':if(ev.target===b)closeModal();break;}});
document.addEventListener('change',ev=>{if(ev.target.name==='assignee'){const detail=ev.target.closest('details');if(detail){const ids=[...detail.querySelectorAll('input:checked')].map(x=>x.value);detail.querySelector('summary').textContent=aNames(ids)}}});
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.dataset.form)return;if(['auth','group-create','group-join','group2','event2','notice2','menu','charge','car-options2','member'].includes(f.dataset.form))return;ev.preventDefault();const fd=new FormData(f),get=n=>String(fd.get(n)||'').trim(),ids=fd.getAll('assignee').map(String),notifs=fd.getAll('notify').map(String),id=f.dataset.id;checkpoint();switch(f.dataset.form){case'task':{const old=state.tasks.find(x=>x.id===id);const v={id:id||UID(),title:get('title'),date:get('date'),time:get('time'),assignees:ids,memo:get('memo'),notifications:notifs,done:old?.done||false,relatedEventId:get('related')||undefined,assignmentNeedsReview:false};if(!v.title||!v.date||!v.time)return;old?Object.assign(old,v):state.tasks.push(v);taskSaveMotion(f);persist();go('tasks');break}case'event':{if(get('start')&&get('end')&&get('end')<get('start')){toast('終了時刻を確認してください');return}const old=event(id),v={id:id||UID(),title:get('title'),date:get('date'),start:get('start'),end:get('end'),kind:get('kind'),venueId:get('venue'),assignees:ids,memo:get('memo'),notifications:notifs};old?Object.assign(old,v):state.events.push(v);if(v.kind==='club')state.people.forEach(m=>{const k=v.id+'|'+m.id;if(!(k in state.attendance))state.attendance[k]=m.defaultOverride??(m.seniority==='below')});persist();go('event/'+v.id);break}case'notice':{const old=state.notices.find(n=>n.id===id),v={id:id||UID(),title:get('title'),body:get('body'),assignees:ids,notify:fd.has('push'),author:old?.author||oName(state.currentUser),date:old?.date||DEMO_TODAY};old?Object.assign(old,v):state.notices.unshift(v);persist();go('notices');break}case'venue':{const v={id:id||UID(),name:get('name'),courts:Number(get('courts')),memo:get('memo')};if(!v.name||!Number.isInteger(v.courts)||v.courts<1)return;const old=venue(id);old?Object.assign(old,v):state.venues.push(v);persist();go('venues');break}case'equipment':{const v={id:id||UID(),name:get('name'),quantity:Number(get('quantity')),unit:get('unit'),memo:get('memo'),threshold:get('threshold')===''?null:Number(get('threshold'))};if(!Number.isFinite(v.quantity)||v.quantity<0||!v.name)return;const old=state.equipment.find(x=>x.id===id);old?Object.assign(old,v):state.equipment.push(v);persist();go('equipment');break}case'member':{const old=person(id),v={id:id||UID(),name:get('name'),grade:Number(get('grade')),seniority:get('seniority'),pickup:get('pickup'),memo:get('memo'),defaultOverride:get('defaultOverride')==='default'?null:get('defaultOverride')==='true',active:true};old?Object.assign(old,v):state.people.push(v);if(!old)clubEvents().filter(e=>e.date>=DEMO_TODAY).forEach(e=>state.attendance[e.id+'|'+v.id]=v.defaultOverride??(v.seniority==='below'));persist();go('members');break}case'group':state.group.name=get('name');persist();go('settings');break;case'notifications':state.settings.reminders=notifs;persist();go('settings');break;case'carsettings':state.settings.unitYen=get('unitYen')===''?null:Number(get('unitYen'));persist();go('settings');break;case'role':state.roles[f.dataset.name]=ids;persist();closeModal();render();break}if(typeof ctx==='undefined'||ctx.mode==='demo')toast('保存しました');});
// Pointer Events。タッチは⠿ハンドルから、名前タップは選択→行き先タップ。
let drag=null,scrollFrame=0;
document.addEventListener('pointerdown',ev=>{lastDragUntil=0;const el=ev.target.closest('[data-person]');if(!el||getRoute()[0]!=='car'||ev.button!==0)return;if(ev.pointerType==='touch'&&!ev.target.closest('.grip'))return;drag={el,mid:el.dataset.person,startX:ev.clientX,startY:ev.clientY,x:ev.clientX,y:ev.clientY,active:false,ghost:null,target:null,pointerId:ev.pointerId};try{el.setPointerCapture(ev.pointerId)}catch{} });
function scrollDrag(){if(!drag?.active)return;const hit=document.elementFromPoint(drag.x,drag.y);const pane=hit?.closest('.scroll-pane');if(pane){const r=pane.getBoundingClientRect();if(drag.y<r.top+28)pane.scrollTop-=7;else if(drag.y>r.bottom-28)pane.scrollTop+=7}scrollFrame=requestAnimationFrame(scrollDrag)}
document.addEventListener('pointermove',ev=>{if(!drag||ev.pointerId!==drag.pointerId)return;drag.x=ev.clientX;drag.y=ev.clientY;if(!drag.active&&Math.hypot(drag.x-drag.startX,drag.y-drag.startY)>7){drag.active=true;drag.ghost=document.createElement('div');drag.ghost.className='drag-ghost';drag.ghost.textContent=pName(drag.mid);document.body.appendChild(drag.ghost);scrollFrame=requestAnimationFrame(scrollDrag)}if(!drag.active)return;ev.preventDefault();drag.ghost.style.transform=`translate(${drag.x-35}px,${drag.y-20}px)`;document.querySelectorAll('.drop-over').forEach(x=>x.classList.remove('drop-over'));const target=document.elementFromPoint(drag.x,drag.y)?.closest('[data-drop]');drag.target=target;target?.classList.add('drop-over')},{passive:false});
function finishDrag(ev,cancelled=false){if(!drag||ev.pointerId!==drag.pointerId)return;const d=drag;drag=null;cancelAnimationFrame(scrollFrame);document.querySelectorAll('.drop-over').forEach(x=>x.classList.remove('drop-over'));d.ghost?.remove();if(d.active){lastDragUntil=Date.now()+400;if(!cancelled&&d.target)performMove(d.mid,destinationFrom(d.target));}}
document.addEventListener('pointerup',ev=>finishDrag(ev));document.addEventListener('pointercancel',ev=>finishDrag(ev,true));
// 共有画像: データから描画。AI生成画像やスマホスクリーンショットを使用しない。
function drawCarCanvas(id){const p=plan(id),e=event(p.eventId),parts=tableParts(p);const colW=168,pad=30,rowsH=46,headH=48;const width=Math.max(520,pad*2+Math.max(1,...parts.map(s=>s.cars.length))*colW);let height=95+parts.reduce((a,s)=>a+40+headH+Math.max(1,...s.cars.map(c=>c.riders.length))*rowsH+20,0);const canvas=document.createElement('canvas');canvas.width=width*2;canvas.height=height*2;const c=canvas.getContext('2d');c.scale(2,2);c.fillStyle='#fff';c.fillRect(0,0,width,height);c.fillStyle='#18211c';c.font='600 22px "Noto Sans CJK JP", sans-serif';c.fillText(`${jpDate(e.date)} ${eventVenue(e)?.name||e.title}${p.linked?'（往復）':''}`,pad,43);let y=85;for(const s of parts){c.fillStyle='#3e5044';c.font='500 14px "Noto Sans CJK JP", sans-serif';c.fillText(s.label+(p.linked?'':'（'+s.legLabel+'）'),pad,y);y+=15;const rows=Math.max(1,...s.cars.map(c=>c.riders.length));s.cars.forEach((car,i)=>{const x=pad+i*colW;c.fillStyle='#edf7f0';c.fillRect(x,y,colW,headH);c.strokeStyle='#dce5df';c.lineWidth=1;c.strokeRect(x,y,colW,headH);c.textAlign='center';c.fillStyle='#18211c';c.font='600 18px "Noto Sans CJK JP", sans-serif';c.fillText(pName(car.driver),x+colW/2,y+31);for(let k=0;k<rows;k++){c.strokeRect(x,y+headH+k*rowsH,colW,rowsH);c.font='400 17px "Noto Sans CJK JP", sans-serif';if(car.riders[k])c.fillText(pName(car.riders[k]),x+colW/2,y+headH+k*rowsH+29)}c.textAlign='left'});y+=headH+rows*rowsH+43}return canvas;}
async function exportCar(id){if(invalid(plan(id)).length){toast('未配車・運転者を確認してください');return}const canvas=drawCarCanvas(id);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob){toast('画像を作成できませんでした');return}const e=event(plan(id).eventId),filename=`配車表_${e.date}.png`;const file=new File([blob],filename,{type:'image/png'});try{if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({files:[file],title:'配車表'});return}}catch(err){if(err.name==='AbortError')return}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
window.addEventListener('hashchange',()=>{ui.selectedPerson=null;closeModal();window.scrollTo(0,0);render()});

function attendanceMemberMonths(p){
 const months=new Map();for(const e of clubEvents().filter(e=>e.date>=DEMO_TODAY&&e.date<=ClubDomain.addMonths(DEMO_TODAY,3)).sort((a,b)=>a.date.localeCompare(b.date))){const month=e.date.slice(0,7);if(!months.has(month))months.set(month,[]);months.get(month).push(e);}
 return '<div style="height:12px"></div>'+[...months].map(([month,events])=>{const key=JSON.stringify([state.group.id,p.id,month]),open=ui.attendanceMonths?.[key]??(month===DEMO_TODAY.slice(0,7));return `<details class="op-car-month" data-attendance-month="${esc(key)}" ${open?'open':''}><summary>${Number(month.slice(0,4))}年${Number(month.slice(5))}月</summary>${events.map(e=>`<button class="row" data-act="attendance-toggle" data-eid="${e.id}" data-mid="${p.id}"><div class="row-main"><div class="row-title">${jpDate(e.date)}</div><div class="row-sub">${e.start||''}　${esc(eventVenue(e)?.name||'')}</div></div><span class="attendance-state ${participates(e.id,p.id)?'yes':''}">${participates(e.id,p.id)?'参加':'不参加'}</span></button>`).join('')}</details>`;}).join('');
}
window.addEventListener('toggle',ev=>{const key=ev.target.dataset?.attendanceMonth;if(key){ui.attendanceMonths||={};ui.attendanceMonths[key]=ev.target.open;}},true);

function taskSaveMotion(form){
 if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
 const panel=form.closest('.modal')||form.closest('main');if(!panel||!panel.animate)return;
 const rect=panel.getBoundingClientRect(),copy=panel.cloneNode(true);copy.inert=true;copy.setAttribute('aria-hidden','true');copy.removeAttribute('id');copy.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));
 Object.assign(copy.style,{position:'fixed',left:rect.left+'px',top:rect.top+'px',width:rect.width+'px',height:rect.height+'px',margin:'0',zIndex:'100',pointerEvents:'none',background:'#fff',overflow:'hidden'});document.body.appendChild(copy);
 const animation=copy.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(24px)'}],{duration:240,easing:'cubic-bezier(.2,.7,.2,1)',fill:'forwards'});animation.onfinish=()=>copy.remove();animation.oncancel=()=>copy.remove();
}
